// Every .latte under packages/ (generated by kit-compose / compose-gen, and the kit primitives) must compile silently with
// the real Latte: Latte 3.1 deprecates unqualified PHP constants in expressions (ENT_QUOTES -> \ENT_QUOTES), the notice is
// raised only on a cold cache, and bare PHP (php -n) prints it to stdout, which broke the JSON of the Latte parity run.
// Two checks: a static scan (no toolchain needed) of the .latte files and of the generator sources that emit Latte, and the
// real Latte compiler over every file (php -n, no cache). Without php + test/server/vendor the compiler check is skipped
// with a message; UI8KIT_REQUIRE_ALL_RUNTIMES=1 (CI) makes that a failure.
import { test, expect } from "bun:test";
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

const REPO = path.resolve(import.meta.dir, "../../..");
const SRV = path.resolve(import.meta.dir, "server");
const REQUIRED = process.env.UI8KIT_REQUIRE_ALL_RUNTIMES === "1";

const tracked = (...globs: string[]) =>
  execFileSync("git", ["ls-files", "-z", "--", ...globs], { cwd: REPO, encoding: "utf8" }).split("\0").filter(Boolean);
const LATTE = tracked("packages/**/*.latte");
// generator sources that write Latte markup as text (the hand-written compositions, the server and organism emitters)
const GENERATORS = tracked("packages/kit-compose/src/*.ts", "packages/compose-gen/*.ts", "packages/compose-gen/screens/src/*.ts", "packages/compose-gen/runtimes/*/src/*.ts");

// PHP constant families that read as unqualified constants inside a Latte expression; not preceded by \ (qualified),
// :: (class constant), $ / -> (variables, properties), a word char or a quote / dot / dash (identifiers, strings, keys)
const PHP_CONST = /(?<![\\\w$:'".>-])(?:ENT_\w+|PHP_\w+|JSON_\w+|M_[A-Z0-9_]+|E_(?:ALL|STRICT|NOTICE|WARNING|ERROR|DEPRECATED|USER_\w+)|SORT_\w+|COUNT_\w+|ARRAY_FILTER_\w+|STR_PAD_\w+|PREG_\w+|FILTER_\w+|MB_CASE_\w+|LC_\w+|HTML_\w+|DIRECTORY_SEPARATOR|PATHINFO_\w+|INF|NAN)\b/g;

/** unqualified constants in the PHP expressions of Latte markup: inside {...} tags, outside comments */
function scanLatte(src: string): string[] {
  const hits: string[] = [];
  for (const m of src.replace(/\{\*[\s\S]*?\*\}/g, "").matchAll(/\{[^{}\s][^{}]*\}/g))
    for (const c of m[0].replace(/'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*"/g, "''").matchAll(PHP_CONST)) hits.push(c[0]);
  return hits;
}

test("latte: no unqualified PHP constants in generated .latte (static scan)", () => {
  expect(LATTE.length).toBeGreaterThan(300);
  const bad = LATTE.flatMap((f) => scanLatte(readFileSync(path.join(REPO, f), "utf8")).map((c) => `${f}: ${c} (write \\${c})`));
  expect(bad).toEqual([]);
});

test("latte: no unqualified PHP constants in the generators that emit Latte (static scan)", () => {
  // the Latte text in a TS template literal: a line that carries Latte syntax ({include, {var, {capture, {if, {foreach, n:...)
  const bad = GENERATORS.flatMap((f) => readFileSync(path.join(REPO, f), "utf8").split("\n").flatMap((line, i) =>
    /\{(?:include|var|capture|if|foreach|parameters|define|block|embed)\b|\.latte\b/.test(line) && !/\.php\b|<\?php/.test(line)
      ? scanLatte(line).map((c) => `${f}:${i + 1}: ${c} (write \\\\${c} in the template literal)`) : []));
  expect(bad).toEqual([]);
});

const php = spawnSync("php", ["-n", "-v"], { stdio: "ignore" }).status === 0 && existsSync(path.join(SRV, "vendor/autoload.php"))
  ? null : "php or test/server/vendor missing (composer install -d packages/kit-compose/test/server)";
if (php && !REQUIRED) {
  console.warn(`[skip] latte compile lint: ${php}`);
  test.skip("latte: every .latte compiles without notices (php -n, cold)", () => {});
} else test("latte: every .latte compiles without notices (php -n, cold)", () => {
  if (php) throw new Error(php);
  // php -n: no php.ini, so display_errors goes to stdout as on a bare PHP; the script itself catches every notice
  const raw = execFileSync("php", ["-n", path.join(SRV, "latte-lint.php"), ...LATTE], { cwd: REPO, encoding: "utf8", maxBuffer: 16 << 20 });
  const notices = JSON.parse(raw) as { file: string; message: string }[];
  expect(notices.map((n) => `${n.file}: ${n.message}`)).toEqual([]);
}, 120000);
